			; Main.bas 53: Mode 2
			dw kw_model, 2

			; Main.bas 54: Hyp.FontInit
			dw fn_hyp_fontinit

			; Main.bas 55: Hyp.Vdu 0                         ' the firmware's text off (TXT VDU DISABLE): AMSDOS says "NAME.CYB not
			dw p_hyp_vdu_c, lit_0

			; Main.bas 59: k = Memory.Banks()
			dw fn_memory_banks, var_k

