if7_e:

			; Main.bas 82: ElseIf hk > 0 And hk <= ns Then
			dw if6_e_go
if6_1:
			dw kw_scpgtvl, var_hk, 0
			dw kw_ftov, tmp0
			dw kw_scplevv, var_hk, var_ns
			dw kw_ftov, tmp1
			dw kw_andvv, tmp0, tmp1, tmp0
			dw kw_goto_ifzero_n, tmp0, if6_2

			; Main.bas 83: ToFront hk
			dw p_tofront_c, var_hk

