do5_e:

			; Main.bas 100: Hyp.Vdu 1
			dw p_hyp_vdu_c, lit_1

			; Main.bas 101: Mode 1
			dw kw_model, 1

			; Main.bas 102: Print "CyborgOS ended, "; runs; " programs ran"
			dw kw_printstrvar, str2
			dw kw_printint, var_runs
			dw kw_printstrvar, str3
			dw kw_printnl

			; Main.bas 103: End
			dw kw_printnl0
